// Filter certificates expiring within 14 days
const RENEW_THRESHOLD_DAYS = 14;
const now = new Date();
const results = [];

for (const item of $input.all()) {
  const cert = item.json;
  if (!cert.expiryDate) continue;

  // Parse expiry date (format: YYYY-MM-DD HH:MM:SS+00:00 or similar)
  const expiry = new Date(cert.expiryDate);
  const daysLeft = Math.floor((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));

  if (daysLeft < RENEW_THRESHOLD_DAYS) {
    results.push({
      json: {
        certificateName: cert.certificateName,
        domains: cert.domains || [],
        expiryDate: cert.expiryDate,
        daysLeft: daysLeft,
        domainsString: (cert.domains || []).join(',')
      }
    });
  }
}

if (results.length === 0) {
  // No certs need renewal - output a summary item
  return [{ json: { message: 'No certificates need renewal', renewed: 0, _skipRenewal: true } }];
}

return results;

// Collect renewal results into a summary
const items = $input.all();
const results = [];
let renewed = 0;
let failed = 0;

for (const item of items) {
  if (item.json.success) {
    renewed++;
    results.push(`  Renewed: ${item.json.domain} (expires ${item.json.expiryDate})`);
  } else {
    failed++;
    results.push(`  FAILED: ${item.json.domain || 'unknown'} - ${item.json.message || item.json.error || 'unknown error'}`);
  }
}

const summary = [
  `Certificate Auto-Renewal Summary (${new Date().toISOString().split('T')[0]})`,
  `  Renewed: ${renewed}`,
  `  Failed:  ${failed}`,
  '',
  ...results
].join('\n');

return [{ json: { summary, renewed, failed, timestamp: new Date().toISOString() } }];
